<?php require __DIR__.'/bootstrap.php';auth();require __DIR__.'/layout.php';$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$pdo->prepare('UPDATE cg_people SET name=?,phone=?,memo=? WHERE id=?')->execute([trim($_POST['name']),phone($_POST['phone']??''),trim($_POST['memo']??''),(int)$_POST['id']]);redirect('people.php');}$q=trim($_GET['q']??'');$st=$pdo->prepare('SELECT p.*,COUNT(e.id) cnt,COALESCE(SUM(e.amount),0) total FROM cg_people p LEFT JOIN cg_expenses e ON e.person_id=p.id WHERE p.name LIKE ? GROUP BY p.id ORDER BY p.name LIMIT 500');$st->execute(['%'.$q.'%']);top('대상자 및 연락처');?><form class="mb-3"><input class="form-control" name="q" value="<?=h($q)?>" placeholder="이름 검색 후 Enter"></form><div class="card p-3"><div class="table-responsive"><table class="table"><thead><tr><th>이름</th><th>전화번호</th><th>비고</th><th>지급이력</th><th>저장</th></tr></thead><tbody><?php foreach($st as $p):?><tr><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="id" value="<?=$p['id']?>"><td><input class="form-control" name="name" value="<?=h($p['name'])?>" required></td><td><input class="form-control" name="phone" value="<?=h($p['phone'])?>" placeholder="010..."></td><td><input class="form-control" name="memo" value="<?=h($p['memo'])?>"></td><td><?=$p['cnt']?>건 / <?=number_format($p['total'])?>만원</td><td><button class="btn btn-sm btn-primary">저장</button></td></form></tr><?php endforeach;?></tbody></table></div></div><?php bottom();?>
